int type_artifact_quest::GetAIValue(int player)
{
    int total = 0;

    for (unsigned i = 0; i < artifacts.size(); ++i) {
        type_artifact wanted;

        wanted.artifactId = artifacts[i];
        wanted.extra = -1;
        total += AI_get_value_of_artifact(&wanted, player);
    }
    return total;
}

